//! Batch ingestion for the telemetry pipeline.
//!
//! Records arrive as comma-separated lines from the edge collector and are
//! validated before they are written into the shared buffer.

use std::collections::HashMap;

/// The maximum number of fields a well-formed record may contain.
const FIELD_LIMIT: usize = 8;

/// A single parsed record; the first element of the device tuple is the
/// collector identifier and the second is the signature of its payload.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Record {
    pub device: (String, String),
    pub sequence: u64,
    pub payload: Vec<u8>,
    pub labels: HashMap<String, String>,
}

/// Errors raised while parsing a raw line.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    Empty,
    TooManyFields(usize),
    BadSequence,
    UnbalancedQuotes,
}

/// Splits a raw line into trimmed fields, rejecting lines that exceed the
/// column limit before the label map is allocated.
fn split_fields(line: &str) -> Result<Vec<String>, ParseError> {
    let fields: Vec<String> = line.split(',').map(|field| field.trim().to_owned()).collect();
    if fields.len() > FIELD_LIMIT {
        return Err(ParseError::TooManyFields(fields.len()));
    }
    Ok(fields)
}

impl Record {
    /// Parses a raw line into a record, returning an error variant when the
    /// field count or the sequence number is malformed.
    pub fn parse(line: &str) -> Result<Record, ParseError> {
        if line.trim().is_empty() {
            return Err(ParseError::Empty);
        }
        let fields = split_fields(line)?;
        if fields.len() < 4 {
            return Err(ParseError::Empty);
        }
        let device = (String::from(&fields[0]), String::from(&fields[1]));
        let sequence = fields[2].parse::<u64>().map_err(|_| ParseError::BadSequence)?;
        let mut labels = HashMap::new();
        for pair in fields.iter().skip(4) {
            if let Some((key, value)) = pair.split_once('=') {
                labels.insert(key.to_owned(), value.to_owned());
            }
        }
        Ok(Record { device, sequence, payload: Vec::new(), labels })
    }
}

/// Validates a batch of raw lines and returns the records in sequence order.
pub fn validate_batch(lines: &[String]) -> Result<Vec<Record>, ParseError> {
    let mut records = Vec::with_capacity(lines.len());
    for line in lines {
        records.push(Record::parse(line)?);
    }
    records.sort_by_key(|record| record.sequence);
    Ok(records)
}

pub struct Writer {
    buffer: Vec<u8>,
}

impl Writer {
    pub fn new() -> Writer {
        Writer { buffer: Vec::new() }
    }

    /// Appends a record, prefixing it with the collector identifier and the
    /// sequence number so that downstream consumers can deduplicate.
    pub fn write(&mut self, record: &Record) {
        self.buffer.extend_from_slice(record.device.0.as_bytes());
        self.buffer.push(b',');
        self.buffer.extend_from_slice(record.device.1.as_bytes());
        self.buffer.push(10);
    }
}
